INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_WEL_AMAETHON_MABINO','ENT_WEL_AMAETHON','SRC_MABINOGION','The Mabinogion','The Mabinogion','No husbandman can till or prepare this land, so wild is it, except Amaethon the son of Don, and he will not come with thee by his own free will, and thou wilt not be able to compel him." "It will be easy for me to compass this, although thou mayest think that it will not be easy." "Though thou get this, there is yet that which thou wilt not get.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_ANNWN_MABINO','ENT_WEL_ANNWN','SRC_MABINOGION','The Mabinogion','The Mabinogion','form and semblance, and he himself took his own; and Arawn set forth towards the Court of Annwvyn; and he was rejoiced when he beheld his hosts, and his household, whom he had not seen so long; but they had not known of his absence, and wondered no more at his coming than usual. And that day was spent in joy and merriment; and he sat and conversed with his wife and his nobles.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_ARANRHOD_MABINO','ENT_WEL_ARANRHOD','SRC_MABINOGION','The Mabinogion','The Mabinogion','Thus, "Caer Arianrod" should be taken simply as the "Camp of Arianrod," and not rendered the "Camp of the silver circle," because the latter, though it might possibly have something to do with the reason for which the name was borne by Arianrod herself, had clearly no reference to its application to her camp. It appears to me, then, looking back upon what has been advanced:- I.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_ARAWN_MABINO','ENT_WEL_ARAWN','SRC_MABINOGION','The Mabinogion','The Mabinogion','Swine are they now called." "Who owneth them?" "Pryderi the son of Pwyll; they were sent him from Annwvyn, by Arawn the king of Annwvyn, and still they keep that name, half hog, half pig." "Verily," asked he, "and by what means may they be obtained from him?" "I will go, lord, as one of twelve, in the guise of bards, to seek the swine." "But it may be that he will refuse you," said he.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_BLODEUWEDD_MABINO','ENT_WEL_BLODEUWEDD','SRC_MABINOGION','The Mabinogion','The Mabinogion','And they baptized her, and gave her the name of Blodeuwedd. After she had become his bride, and they had feasted, said Gwydion, "It is not easy for a man to maintain himself without possessions." "Of a truth," said Math, "I will give the young man the best Cantrev to hold." "Lord," said he, "what Cantrev is that?" "The Cantrev of Dinodig," he answered. Now it is called at this day Eivionydd and Ardudwy.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_BRANWEN_MABINO','ENT_WEL_BRANWEN','SRC_MABINOGION','The Mabinogion','The Mabinogion','"That Branwen the daughter of Llyr, one of the three chief ladies of this island, and the daughter of the King of the Island of the Mighty, should have been given me as my bride, and that after that I should have been insulted; and I marvel that the insult was not done me before they had bestowed upon me a maiden so exalted as she." "Truly, lord, it was not the will of any that are of the Court," said they, "nor of any that are of the council, that thou sh','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_CERIDWEN_MABINO','ENT_WEL_CERIDWEN','SRC_MABINOGION','The Mabinogion','The Mabinogion','And one day, towards the end of the year, as Caridwen was culling plants and making incantations, it chanced that three drops of the charmed liquor flew out of the cauldron and fell upon the finger of Gwion Bach.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_CREIDDYLAD_MABINO','ENT_WEL_CREIDDYLAD','SRC_MABINOGION','The Mabinogion','The Mabinogion','* * * * * Said Arthur, "Which of the marvels is it best for us now to seek?" "It is best for us to seek Drudwyn, the cub of Greid the son of Eri." A little while before this, Creiddylad the daughter of Lludd Llaw Ereint, and Gwythyr the son of Greidawl, were betrothed. And before she had become his bride, Gwyn ap Nudd came and carried her away by force; and Gwythyr the son of Greidawl gathered his host together, and went to fight with Gwyn ap Nudd.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_CREIRWY_MABINO','ENT_WEL_CREIRWY','SRC_MABINOGION','The Mabinogion','The Mabinogion','And there was born to him of his wife a son named Morvran ab Tegid, and also a daughter named Creirwy, the fairest maiden in the world was she; and they had a brother, the most ill-favoured man in the world, Avagddu. Now Caridwen his mother thought that he was not likely to be admitted among men of noble birth, by reason of his ugliness, unless he had some exalted merits or knowledge. For it was in the beginning of Arthur''s time and of the Round Table.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_DYLAN_MABINO','ENT_WEL_DYLAN','SRC_MABINOGION','The Mabinogion','The Mabinogion','And for that reason was he called Dylan, the son of the Wave. Beneath him no wave ever broke. And the blow whereby he came to his death, was struck by his uncle Govannon. The third fatal blow was it called. As Gwydion lay one morning on his bed awake, he heard a cry in the chest at his feet; and though it was not loud, it was such that he could hear it.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_EFNYSIEN_MABINO','ENT_WEL_EFNYSIEN','SRC_MABINOGION','The Mabinogion','The Mabinogion','And with him were his brother Manawyddan the son of Llyr, and his brothers by the mother''s side, Nissyen and Evnissyen, and many nobles likewise, as was fitting to see around a king. His two brothers by the mother''s side were the sons of Eurosswydd, by his mother, Penardun, the daughter of Beli son of Manogan.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_GILFAETHWY_MABINO','ENT_WEL_GILFAETHWY','SRC_MABINOGION','The Mabinogion','The Mabinogion','And at night Gwydion the son of Don, and Gilvaethwy his brother, returned to Caer Dathyl; and Gilvaethwy took Math the son of Mathonwy''s couch. And while he turned out the other damsels from the room discourteously, he made Goewin unwillingly remain.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_GOFANNON_MABINO','ENT_WEL_GOFANNON','SRC_MABINOGION','The Mabinogion','The Mabinogion','And the blow whereby he came to his death, was struck by his uncle Govannon. The third fatal blow was it called. As Gwydion lay one morning on his bed awake, he heard a cry in the chest at his feet; and though it was not loud, it was such that he could hear it. Then he arose in haste, and opened the chest: and when he opened it, he beheld an infant boy stretching out his arms from the folds of the scarf, and casting it aside.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_GWYDION_MABINO','ENT_WEL_GWYDION','SRC_MABINOGION','The Mabinogion','The Mabinogion','Gwydion showed him also how he had procured arms for the youth. "Well," said Math, "we will seek, I and thou, by charms and illusion, to form a wife for him out of flowers. He has now come to man''s stature, and he is the comeliest youth that was ever beheld." So they took the blossoms of the oak, and the blossoms of the broom, and the blossoms of the meadow-sweet, and produced from them a maiden, the fairest and most graceful that man ever saw.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_GWYN_AP_NUDD_MABINO','ENT_WEL_GWYN_AP_NUDD','SRC_MABINOGION','The Mabinogion','The Mabinogion','And this was the peace that was made:-that the maiden should remain in her father''s house, without advantage to either of them, and that Gwyn ap Nudd and Gwythyr the son of Greidawl should fight for her every first of May, from thenceforth until the day of doom, and that whichever of them should then be conqueror should have the maiden.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_GWYTHYR_MABINO','ENT_WEL_GWYTHYR','SRC_MABINOGION','The Mabinogion','The Mabinogion','on of Eri." A little while before this, Creiddylad the daughter of Lludd Llaw Ereint, and Gwythyr the son of Greidawl, were betrothed. And before she had become his bride, Gwyn ap Nudd came and carried her away by force; and Gwythyr the son of Greidawl gathered his host together, and went to fight with Gwyn ap Nudd. But Gwyn overcame him, and captured Greid the son of Eri, and Glinneu the son of Taran, and Gwrgwst Ledlwm, and Dynvarth his son.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_HAFGAN_MABINO','ENT_WEL_HAFGAN','SRC_MABINOGION','The Mabinogion','The Mabinogion','epent doing that unto thee, slay thee who may, I will not do so." "My trusty Lords," said Havgan, "bear me hence. My death has come. I shall be no more able to uphold you." "My Nobles," also said he who was in the semblance of Arawn, "take counsel and know who ought to be my subjects." "Lord," said the Nobles, "all should be, for there is no king over the whole of Annwvyn but thee." "Yes," he replied, "it is right that he who comes humbly should be receive','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_LLEU_LLAW_GYFFES_MABINO','ENT_WEL_LLEU_LLAW_GYFFES','SRC_MABINOGION','The Mabinogion','The Mabinogion','rain? Has it not been drenched By nine score tempests? It bears in its branches Llew Llaw Gyffes!" Then the eagle came down until he was on the lowest branch of the tree, and thereupon this Englyn did Gwydion sing:- "Oak that grows beneath the steep; Stately and majestic is its aspect! Shall I not speak it? That Llew will come to my lap?" And the eagle came down upon Gwydion''s knee.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_LLUDD_MABINO','ENT_WEL_LLUDD','SRC_MABINOGION','The Mabinogion','The Mabinogion','the cub of Greid the son of Eri." A little while before this, Creiddylad the daughter of Lludd Llaw Ereint, and Gwythyr the son of Greidawl, were betrothed. And before she had become his bride, Gwyn ap Nudd came and carried her away by force; and Gwythyr the son of Greidawl gathered his host together, and went to fight with Gwyn ap Nudd.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_LLWYD_MABINO','ENT_WEL_LLWYD','SRC_MABINOGION','The Mabinogion','The Mabinogion','"I am Llwyd the son of Kilcoed, and I cast the charm over the seven Cantrevs of Dyved. And it was to avenge Gwawl the son of Clud, from the friendship I had towards him, that I cast the charm. And upon Pryderi did I revenge Gwawl the son of Clud, for the game of Badger in the Bag, that Pwyll Pen Annwvyn played upon him, which he did unadvisedly in the Court of Heveydd Hen.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_MABON_MABINO','ENT_WEL_MABON','SRC_MABINOGION','The Mabinogion','The Mabinogion','Throughout the world there is not a huntsman who can hunt with this dog, except Mabon the son of Modron. He was taken from his mother when three nights old, and it is not known where he now is, nor whether he is living or dead." "It will be easy for me to compass this, although thou mayest think that it will not be easy." "Though thou get this, there is yet that which thou wilt not get.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_MANAWYDAN_MABINO','ENT_WEL_MANAWYDAN','SRC_MABINOGION','The Mabinogion','The Mabinogion','"We will make shields," said Manawyddan. "Do we know anything about that craft?" said Pryderi. "We will try," answered he. There they began to make shields, and fashioned them after the shape of the good shields they had seen; and they enamelled they, as them had done the saddles. And they prospered in that place, so that not a shield was asked for in the whole town, but such as was had of them.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_MATH_MABINO','ENT_WEL_MATH','SRC_MABINOGION','The Mabinogion','The Mabinogion','Be thou of glad cheer therefore, and I will compass it." So they went unto Math the son of Mathonwy. "Lord," said Gwydion, "I have heard that there have come to the South some beasts, such as were never known in this island before." "What are they called?" he asked. "Pigs, lord." "And what kind of animals are they?" "They are small animals, and their flesh is better than the flesh of oxen." "They are small, then?" "And they change their names.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_MODRON_MABINO','ENT_WEL_MODRON','SRC_MABINOGION','The Mabinogion','The Mabinogion','Throughout the world there is not a huntsman who can hunt with this dog, except Mabon the son of Modron. He was taken from his mother when three nights old, and it is not known where he now is, nor whether he is living or dead." "It will be easy for me to compass this, although thou mayest think that it will not be easy." "Though thou get this, there is yet that which thou wilt not get.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_MORFRAN_MABINO','ENT_WEL_MORFRAN','SRC_MABINOGION','The Mabinogion','The Mabinogion','of Kado, and Rheidwn the son of Beli, and Iscovan Hael, and Iscawin the son of Panon, and Morvran the son of Tegid (no one struck him in the battle of Camlan by reason of his ugliness; all thought he was an auxiliary devil. Hair had he upon him like the hair of a stag). And Sandde Bryd Angel (no one touched him with a spear in the battle of Camlan because of his beauty; all thought he was a ministering angel).','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_NISIEN_MABINO','ENT_WEL_NISIEN','SRC_MABINOGION','The Mabinogion','The Mabinogion','and cause his family to be friends when their wrath was at the highest; and this one was Nissyen; but the other would cause strife between his two brothers when they were most at peace. And as they sat thus, they beheld thirteen ships coming from the south of Ireland, and making towards them, and they came with a swift motion, the wind being behind them, and they neared them rapidly. "I see ships afar," said the king, "coming swiftly towards the land.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_OLWEN_MABINO','ENT_WEL_OLWEN','SRC_MABINOGION','The Mabinogion','The Mabinogion','And therefore was she called Olwen. She entered the house, and sat beside Kilhwch upon the foremost bench; and as soon as he saw her he knew her. And Kilhwch said unto her, "Ah! maiden, thou art she whom I have loved; come away with me, lest they speak evil of thee and of me. Many a day have I loved thee." "I cannot do this, for I have pledged my faith to my father not to go without his counsel, for his life will last only until the time of my espousals.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_PENARDDUN_MABINO','ENT_WEL_PENARDDUN','SRC_MABINOGION','The Mabinogion','The Mabinogion','His two brothers by the mother''s side were the sons of Eurosswydd, by his mother, Penardun, the daughter of Beli son of Manogan. And one of these youths was a good youth and of gentle nature, and would make peace between his kindred, and cause his family to be friends when their wrath was at the highest; and this one was Nissyen; but the other would cause strife between his two brothers when they were most at peace.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_PRYDERI_MABINO','ENT_WEL_PRYDERI','SRC_MABINOGION','The Mabinogion','The Mabinogion','MATH THE SON OF MATHONWY THIS IS THE FOURTH PORTION OF THE MABINOGI Math the son of Mathonwy was lord over Gwynedd, and Pryderi the son of Pwyll was lord over the one-and-twenty Cantrevs of the South; and these were the seven Cantrevs of Dyved, and the seven Cantrevs of Morganwc, the four Cantrevs of Ceredigiawn, and the three of Ystrad Tywi.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_PWYLL_MABINO','ENT_WEL_PWYLL','SRC_MABINOGION','The Mabinogion','The Mabinogion','ly, and united the two kingdoms in one day by his valour and prowess, he lost the name of Pwyll Prince of Dyved, and was called Pwyll Chief of Annwvyn from that time forward. * * * * * Once upon a time, Pwyll was at Narberth his chief palace, where a feast had been prepared for him, and with him was a great host of men.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_RHIANNON_MABINO','ENT_WEL_RHIANNON','SRC_MABINOGION','The Mabinogion','The Mabinogion','nwen; and concerning the seven years'' banquet in Harlech, and the singing of the birds of Rhiannon, and the sojourning of the head for the space of fourscore years. MANAWYDDAN THE SON OF LLYR HERE IS THE THIRD PORTION OF THE MABINOGI When the seven men of whom we spoke above had buried the head of Bendigeid Vran, in the White Mount in London, with its face towards France; Manawyddan gazed upon the town of London, and upon his companions, and heaved a great','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_TEGID_FOEL_MABINO','ENT_WEL_TEGID_FOEL','SRC_MABINOGION','The Mabinogion','The Mabinogion','TALIESIN In times past there lived in Penllyn a man of gentle lineage, named Tegid Voel, and his dwelling was in the midst of the lake Tegid, and his wife was called Caridwen. And there was born to him of his wife a son named Morvran ab Tegid, and also a daughter named Creirwy, the fairest maiden in the world was she; and they had a brother, the most ill-favoured man in the world, Avagddu.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_TEYRNON_MABINO','ENT_WEL_TEYRNON','SRC_MABINOGION','The Mabinogion','The Mabinogion','Kulvanawyd the son of Goryon, and Llenlleawg Wyddel from the headland of Ganion, and Dyvynwal Moel, and Dunard king of the North, Teirnon Twryf Bliant, and Tegvan Gloff, and Tegyr Talgellawg, Gwrdinal the son of Ebrei, and Morgant Hael, Gwystyl the son of Rhun the son of Nwython, and Llwyddeu the son of Nwython, and Gwydre the son of Llwyddeu (Gwenabwy the daughter of [Kaw] was his mother, Hueil his uncle stabbed him, and hatred was between Hueil and Arthu','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_YSBADDADEN_MABINO','ENT_WEL_YSBADDADEN','SRC_MABINOGION','The Mabinogion','The Mabinogion','Then said she unto him, "I declare to thee, that it is thy destiny not to be suited with a wife until thou obtain Olwen, the daughter of Yspaddaden Penkawr." And the youth blushed, and the love of the maiden diffused itself through all his frame, although he had never seen her.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1)
